{"file_path":"src/address.js","content":"/**
 * Cell addresses. A column is one or two letters, `A` to `Z` and then `AA` to
 * `ZZ`; a row is one to three digits naming a row of at least 1.
 */

const ADDRESS = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** The 1-based index of a column named by one or two letters. */
export function columnIndex(letters) {
  const upper = letters.toUpperCase()
  let index = 0
  for (const letter of upper) index = index * 26 + (letter.charCodeAt(0) - 64)
  return index
}

/** The letters naming the column with the given 1-based index. */
export function columnLetters(index) {
  if (index <= 26) return String.fromCharCode(64 + index)
  const first = Math.floor((index - 1) / 26)
  const second = index - first * 26
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/**
 * The address named by `text`, or null when `text` names no cell inside the
 * addressable range. The result carries the canonical spelling.
 */
export function parseAddress(text) {
  const match = ADDRESS.exec(text)
  if (match === null) return null
  const row = Number(match[2])
  if (row < 1) return null
  const column = columnIndex(match[1])
  return { column, row, name: columnLetters(column) + row }
}

/** Orders addresses by column and then by row. */
export function compareAddresses(a, b) {
  return a.column - b.column || a.row - b.row
}

/** Every cell covered by the rectangle spanned by two corners, in order. */
export function expandRange(one, other) {
  const firstColumn = Math.min(one.column, other.column)
  const lastColumn = Math.max(one.column, other.column)
  const firstRow = Math.min(one.row, other.row)
  const lastRow = Math.max(one.row, other.row)
  const cells = []
  for (let column = firstColumn; column <= lastColumn; column += 1) {
    const letters = columnLetters(column)
    for (let row = firstRow; row <= lastRow; row += 1) {
      cells.push({ column, row, name: letters + row })
    }
  }
  return cells
}
"}

