{"file_path":"src/sheet.js","content":"/**
 * The sheet reader. A sheet is a list of lines, each naming a cell and giving
 * its content.
 */

import { parseAddress, compareAddresses } from './address.js'

export class SheetError extends Error {}

/**
 * Reads a sheet from the text of a whole input. Throws a SheetError, whose
 * message is the line to write to standard error, at the first bad line.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const line = lines[index].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end += 1
    const written = line.slice(0, end)
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) {
      rest += 1
      break
    }
    const content = line.slice(rest)

    const address = parseAddress(written)
    if (address === null) {
      throw new SheetError(`error: line ${number}: invalid cell address ${written}`)
    }
    if (cells.has(address.name)) {
      throw new SheetError(`error: line ${number}: cell ${address.name} is declared twice`)
    }
    cells.set(address.name, { address, content })
  }

  const declared = [...cells.values()].sort((a, b) => compareAddresses(a.address, b.address))
  return { cells, declared }
}
"}

