{"file_path":"src/formula.js","content":"/**
 * The formula grammar. A body is read into a tree of nodes; anything the
 * grammar does not accept is a FormulaError, which the caller reads as `#ERR!`.
 */

export class FormulaError extends Error {}

const NUMBER = /[0-9]+(\.[0-9]+)?/y
const WORD = /[A-Za-z][A-Za-z0-9]*/y
const OPERATORS = ['<>', '<=', '>=', '^', '*', '/', '+', '-', '=', '<', '>']

function lex(body) {
  const tokens = []
  let at = 0
  while (at < body.length) {
    const character = body[at]
    if (character === ' ' || character === '\t') {
      at += 1
      continue
    }
    if (character === '(' || character === ')' || character === ',' || character === ':') {
      tokens.push({ kind: character })
      at += 1
      continue
    }
    NUMBER.lastIndex = at
    const number = NUMBER.exec(body)
    if (number !== null) {
      tokens.push({ kind: 'number', text: number[0] })
      at = NUMBER.lastIndex
      continue
    }
    WORD.lastIndex = at
    const word = WORD.exec(body)
    if (word !== null) {
      tokens.push({ kind: 'word', text: word[0] })
      at = WORD.lastIndex
      continue
    }
    const operator = OPERATORS.find((candidate) => body.startsWith(candidate, at))
    if (operator !== undefined) {
      tokens.push({ kind: 'operator', text: operator })
      at += operator.length
      continue
    }
    throw new FormulaError(`unexpected character ${character}`)
  }
  tokens.push({ kind: 'end' })
  return tokens
}

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek() {
    return this.tokens[this.at]
  }

  take() {
    const token = this.tokens[this.at]
    this.at += 1
    return token
  }

  operator(names) {
    const token = this.peek()
    if (token.kind === 'operator' && names.includes(token.text)) {
      this.at += 1
      return token.text
    }
    return null
  }

  expect(kind) {
    const token = this.take()
    if (token.kind !== kind) throw new FormulaError(`expected ${kind}`)
    return token
  }

  expression() {
    let left = this.additive()
    for (;;) {
      const operator = this.operator(COMPARISONS)
      if (operator === null) return left
      left = { type: 'binary', operator, left, right: this.additive() }
    }
  }

  additive() {
    let left = this.multiplicative()
    for (;;) {
      const operator = this.operator(['+', '-'])
      if (operator === null) return left
      left = { type: 'binary', operator, left, right: this.multiplicative() }
    }
  }

  multiplicative() {
    let left = this.power()
    for (;;) {
      const operator = this.operator(['*', '/'])
      if (operator === null) return left
      left = { type: 'binary', operator, left, right: this.power() }
    }
  }

  power() {
    const left = this.unary()
    const operator = this.operator(['^'])
    if (operator === null) return left
    return { type: 'binary', operator, left, right: this.power() }
  }

  unary() {
    const operator = this.operator(['-', '+'])
    if (operator === null) return this.primary()
    return { type: 'unary', operator, operand: this.unary() }
  }

  primary() {
    const token = this.take()
    if (token.kind === 'number') return { type: 'number', value: Number(token.text) }
    if (token.kind === '(') {
      const inner = this.expression()
      this.expect(')')
      return { type: 'group', inner }
    }
    if (token.kind === 'word') {
      if (this.peek().kind === '(') {
        this.take()
        const args = []
        if (this.peek().kind !== ')') {
          args.push(this.expression())
          while (this.peek().kind === ',') {
            this.take()
            args.push(this.expression())
          }
        }
        this.expect(')')
        return { type: 'call', name: token.text, args }
      }
      if (this.peek().kind === ':') {
        this.take()
        const end = this.expect('word')
        return { type: 'range', from: token.text, to: end.text }
      }
      return { type: 'word', text: token.text }
    }
    throw new FormulaError('unexpected token')
  }
}

/** The tree of a formula body, or a thrown FormulaError. */
export function parseFormula(body) {
  const parser = new Parser(lex(body))
  const node = parser.expression()
  parser.expect('end')
  return node
}

/**
 * Whether a range sits anywhere but directly as a function argument, which the
 * grammar accepts but the sheet does not.
 */
export function hasMisplacedRange(node) {
  switch (node.type) {
    case 'range':
      return true
    case 'group':
      return hasMisplacedRange(node.inner)
    case 'unary':
      return hasMisplacedRange(node.operand)
    case 'binary':
      return hasMisplacedRange(node.left) || hasMisplacedRange(node.right)
    case 'call':
      return node.args.some((arg) => arg.type !== 'range' && hasMisplacedRange(arg))
    default:
      return false
  }
}
"}

