{"file_path":"src/values.js","content":"/** Values: a number, text, a boolean, or an error. */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const number = (value) => ({ kind: 'number', value })
export const text = (value) => ({ kind: 'text', value })
export const boolean = (value) => ({ kind: 'boolean', value })
export const error = (token) => ({ kind: 'error', token })

export const DIV0 = error('#DIV/0!')
export const REF = error('#REF!')
export const VALUE = error('#VALUE!')
export const CYCLE = error('#CYCLE!')
export const NAME = error('#NAME?')
export const ERR = error('#ERR!')

export const isError = (value) => value.kind === 'error'

/** A number, or `#DIV/0!` when arithmetic left the finite numbers behind. */
export function finite(value) {
  return Number.isFinite(value) ? number(value) : DIV0
}

/** A value in an arithmetic position: a boolean counts, and text does not. */
export function toNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return number(value.value ? 1 : 0)
  if (value.kind === 'error') return value
  return VALUE
}

const RANK = { number: 0, text: 1, boolean: 2 }

function compareText(left, right) {
  const one = [...left]
  const other = [...right]
  const shared = Math.min(one.length, other.length)
  for (let at = 0; at < shared; at += 1) {
    const a = one[at].codePointAt(0)
    const b = other[at].codePointAt(0)
    if (a !== b) return a < b ? -1 : 1
  }
  return one.length - other.length === 0 ? 0 : one.length < other.length ? -1 : 1
}

/** Orders two values: every number below every text below every boolean. */
export function compareValues(left, right) {
  if (RANK[left.kind] !== RANK[right.kind]) return RANK[left.kind] < RANK[right.kind] ? -1 : 1
  if (left.kind === 'number') return left.value === right.value ? 0 : left.value < right.value ? -1 : 1
  if (left.kind === 'text') return compareText(left.value, right.value)
  return left.value === right.value ? 0 : left.value ? 1 : -1
}

/** A number as JavaScript prints it once rounded to ten significant digits. */
export function formatNumber(value) {
  return String(Number(value.toPrecision(10)))
}

/** A value as the `values` mode prints it. */
export function formatValue(value) {
  if (value.kind === 'number') return formatNumber(value.value)
  if (value.kind === 'boolean') return value.value ? 'TRUE' : 'FALSE'
  if (value.kind === 'error') return value.token
  return value.value
}

const LITERAL_NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

/** The value of a literal, which is anything that does not begin with `=`. */
export function literalValue(content) {
  if (content === '') return number(0)
  if (LITERAL_NUMBER.test(content)) return number(Number(content))
  if (ERROR_TOKENS.includes(content)) return error(content)
  return text(content)
}
"}

