  /** The tree of a cell's formula, or a FormulaError kept from the first read. */
  tree(name, body) {
    if (!this.trees.has(name)) {
      try {
        this.trees.set(name, { node: parseFormula(body) })
      } catch (cause) {
        if (!(cause instanceof FormulaError)) throw cause
        this.trees.set(name, { node: null })
      }
    }
    return this.trees.get(name).node
  }

