  single(node) {
    const values = this.argument(node)
    const first = values.find(isError)
    if (first !== undefined) return first
    if (values.length !== 1) return VALUE
    return values[0]
  }

  evaluate(node) {
    switch (node.type) {
      case 'number':
        return number(node.value)
      case 'group':
        return this.evaluate(node.inner)
      case 'word':
        return this.word(node.text)
      case 'range':
        return ERR
      case 'unary':
        return this.unary(node)
      case 'binary':
        return this.binary(node)
      case 'call':
        return this.call(node)
      default:
        return ERR
    }
  }

  word(text) {
    const upper = text.toUpperCase()
    if (upper === 'TRUE') return boolean(true)
    if (upper === 'FALSE') return boolean(false)
