      } catch (cause) {
        if (!(cause instanceof FormulaError)) throw cause
        this.trees.set(name, { node: null })
      }
    }
    return this.trees.get(name).node
  }

  /** The value of a cell, which is 0 when nobody declared it. */
  value(name) {
    if (this.values.has(name)) return this.values.get(name)
    const cell = this.cells.get(name)
    if (cell === undefined) return number(0)
    if (this.pending.has(name)) return CYCLE
    this.pending.add(name)
    let result
    try {
      result = this.compute(name, cell.content)
    } finally {
      this.pending.delete(name)
    }
    this.values.set(name, result)
    return result
  }

  compute(name, content) {
    if (!isFormula(content)) return literalValue(content)
    const node = this.tree(name, content.slice(1))
    if (node === null) return ERR
    if (hasMisplacedRange(node)) return ERR
    return this.evaluate(node)
  }

  /** The cells a range covers, or null when a corner names no cell. */
  static rangeCells(node) {
    const from = parseAddress(node.from)
    const to = parseAddress(node.to)
    if (from === null || to === null) return null
    return expandRange(from, to)
  }

  /** The values an argument contributes, a range contributing every cell. */
  argument(node) {
    if (node.type === 'range') {
      const cells = Engine.rangeCells(node)
      if (cells === null) return [REF]
      return cells.map((cell) => this.value(cell.name))
    }
    return [this.evaluate(node)]
  }

  /** The one value an argument contributes, where only one will do. */
  single(node) {
    const values = this.argument(node)
    const first = values.find(isError)
    if (first !== undefined) return first
    if (values.length !== 1) return VALUE
    return values[0]
  }

  evaluate(node) {
    switch (node.type) {
      case 'number':
        return number(node.value)
      case 'group':
        return this.evaluate(node.inner)
      case 'word':
        return this.word(node.text)
      case 'range':
        return ERR
      case 'unary':
        return this.unary(node)
      case 'binary':
        return this.binary(node)
      case 'call':
        return this.call(node)
      default:
        return ERR
    }
  }

  word(text) {
    const upper = text.toUpperCase()
    if (upper === 'TRUE') return boolean(true)
    if (upper === 'FALSE') return boolean(false)
    const address = parseAddress(upper)
    if (address === null) return REF
    return this.value(address.name)
  }

  unary(node) {
    const operand = this.evaluate(node.operand)
    if (isError(operand)) return operand
    const value = toNumber(operand)
    if (isError(value)) return value
    return finite(node.operator === '-' ? -value.value : value.value)
  }

  binary(node) {
    const operator = node.operator
    const left = this.evaluate(node.left)
    if (['=', '<>', '<', '<=', '>', '>='].includes(operator)) {
      if (isError(left)) return left
      const right = this.evaluate(node.right)
      if (isError(right)) return right
      const order = compareValues(left, right)
      switch (operator) {
        case '=':
          return boolean(order === 0)
        case '<>':
          return boolean(order !== 0)
        case '<':
          return boolean(order < 0)
        case '<=':
          return boolean(order <= 0)
        case '>':
          return boolean(order > 0)
        default:
          return boolean(order >= 0)
      }
    }
    if (isError(left)) return left
    const one = toNumber(left)
    if (isError(one)) return one
    const right = this.evaluate(node.right)
    if (isError(right)) return right
    const other = toNumber(right)
    if (isError(other)) return other
    switch (operator) {
      case '+':
        return finite(one.value + other.value)
      case '-':
        return finite(one.value - other.value)
      case '*':
        return finite(one.value * other.value)
      case '/':
        return other.value === 0 ? DIV0 : finite(one.value / other.value)
      default:
        return finite(one.value ** other.value)
    }
  }

  call(node) {
    const name = node.name.toUpperCase()
    if (!Object.hasOwn(ARITIES, name)) return NAME
    const arity = ARITIES[name]
    if (arity === null ? node.args.length < 1 : node.args.length !== arity) return ERR
    if (name === 'IF') return this.conditional(node)

    const values = node.args.flatMap((arg) => this.argument(arg))
    const first = values.find(isError)
    if (first !== undefined) return first
    if (name === 'COUNT') return number(values.filter((value) => value.kind === 'number').length)
    if (name === 'ABS') {
      if (values.length !== 1) return VALUE
      const only = toNumber(values[0])
      return isError(only) ? only : finite(Math.abs(only.value))
    }
    const numbers = []
    for (const value of values) {
      const converted = toNumber(value)
      if (isError(converted)) return converted
      numbers.push(converted.value)
    }
    switch (name) {
      case 'SUM':
        return finite(numbers.reduce((total, each) => total + each, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      default:
        return finite(numbers.reduce((total, each) => total + each, 0) / numbers.length)
    }
  }

  conditional(node) {
    const condition = this.single(node.args[0])
    if (isError(condition)) return condition
    let taken
    if (condition.kind === 'boolean') taken = condition.value
    else if (condition.kind === 'number') taken = condition.value !== 0
    else return VALUE
    return this.single(node.args[taken ? 1 : 2])
  }

  /** The distinct cells a content names directly, ranges expanded, in order. */
  dependencies(name, content) {
    if (!isFormula(content)) return []
    const node = this.tree(name, content.slice(1))
    if (node === null) return []
    const found = new Map()
    collect(node, found)
    return [...found.values()].sort(compareAddresses).map((address) => address.name)
  }
}

function collect(node, found) {
  switch (node.type) {
    case 'word': {
      const upper = node.text.toUpperCase()
      if (upper === 'TRUE' || upper === 'FALSE') return
      const address = parseAddress(upper)
      if (address !== null) found.set(address.name, address)
      return
    }
    case 'range': {
      const cells = Engine.rangeCells(node)
      if (cells !== null) for (const cell of cells) found.set(cell.name, cell)
      return
    }
    case 'group':
      collect(node.inner, found)
      return
    case 'unary':
      collect(node.operand, found)
      return
    case 'binary':
      collect(node.left, found)
      collect(node.right, found)
      return
    case 'call':
      for (const arg of node.args) collect(arg, found)
      return
    default:
  }
}

export { error }
"}

