{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Engine } from './evaluate.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'values' && mode !== 'deps') fail('error: usage: cli.js values|deps')

  let sheet
  try {
    sheet = parseSheet(readInput())
  } catch (cause) {
    if (!(cause instanceof SheetError)) throw cause
    return fail(cause.message)
  }

  const engine = new Engine(sheet.cells)
  const lines = []
  for (const cell of sheet.declared) {
    const name = cell.address.name
    if (mode === 'values') {
      lines.push(`${name}=${formatValue(engine.value(name))}`)
    } else {
      const named = engine.dependencies(name, cell.content)
      lines.push(`${name}:${named.map((each) => ` ${each}`).join('')}`)
    }
  }
  if (lines.length > 0) process.stdout.write(`${lines.join('\n')}\n`)
}

main(process.argv.slice(2))
"}

